def xor_of_range(a, b):
    def prefix_xor(n):
        if n < 0:
            return 0
        remainder = n % 4
        table = {0: n, 1: 1, 2: n + 1, 3: 0}
        return table[remainder]
    return prefix_xor(b) ^ prefix_xor(a - 1)

def oxford_join_or(items):
    n = len(items)
    if n == 0:
        return ''
    if n == 1:
        return items[0]
    if n == 2:
        return f'{items[0]} or {items[1]}'
    return ', '.join(items[:-1]) + f', or {items[-1]}'

