def shared_key_sum(dicts_list):
    totals = {}
    occurrences = {}
    for d in dicts_list:
        for key, value in d.items():
            totals[key] = totals.get(key, 0) + value
            occurrences[key] = occurrences.get(key, 0) + 1
    return {key: totals[key] for key in totals if occurrences[key] >= 2}

