def longest_non_decreasing_run_length(lst):
    if not lst:
        return 0
    longest = 1
    current = 1
    for i in range(1, len(lst)):
        if lst[i] >= lst[i - 1]:
            current += 1
            if current > longest:
                longest = current
        else:
            current = 1
    return longest

