def is_near_palindrome(s):
    def is_pal(sub):
        return sub == sub[::-1]

    i, j = 0, len(s) - 1
    while i < j:
        if s[i] != s[j]:
            return is_pal(s[i + 1:j + 1]) or is_pal(s[i:j])
        i += 1
        j -= 1
    return True

def nth_weekday_of_month(year, month, weekday_num, n):
    days_in_month = [31, 29 if (year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)) else 28,
                      31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    def wd(y, m, d):
        if m < 3:
            m += 12
            y -= 1
        k = y % 100
        j = y // 100
        h = (d + (13 * (m + 1)) // 5 + k + k // 4 + j // 4 + 5 * j) % 7
        return (h + 5) % 7
    count = 0
    for day in range(1, days_in_month[month - 1] + 1):
        if wd(year, month, day) == weekday_num:
            count += 1
            if count == n:
                return day
    return -1

